public boolean canReach(BlockPos pos) {
        Path path = this.getNavigation().createPath(pos, 0);
        if (path == null) {
            return false;
        } else {
            Node node = path.getEndNode();
            if (node == null) {
                return false;
            } else {
                int i = node.x - pos.getX();
                int j = node.y - pos.getY();
                int k = node.z - pos.getZ();
                return (double) (i * i + j * j + k * k) <= 3D;
            }
        }
    }

